from functools import lru_cache

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [[0] * w for _ in range(h)]

    idx = {p: i for i, p in enumerate(cells)}
    full = (1 << len(cells)) - 1
    tiles = []

    # Each 2x2 square is color 1. The three-cell shapes are colored
    # according to the missing corner.
    corner_color = {
        (0, 0): 2,  # missing upper-left
        (1, 0): 3,  # missing lower-left
        (0, 1): 4,  # missing upper-right
    }
    for r in range(h - 1):
        for c in range(w - 1):
            block = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            if all(p in idx for p in block):
                mask = sum(1 << idx[p] for p in block)
                tiles.append((mask, 1, 1))
            for missing in corner_color:
                present = [p for p in block if p != (r + missing[0], c + missing[1])]
                if all(p in idx for p in present):
                    mask = sum(1 << idx[p] for p in present)
                    tiles.append((mask, corner_color[missing], 0))

    by_cell = [[] for _ in cells]
    for mask, color, square in tiles:
        for i in range(len(cells)):
            if mask >> i & 1:
                by_cell[i].append((mask, color, square))
    for options in by_cell:
        options.sort(key=lambda t: (-t[2], t[1]))

    @lru_cache(None)
    def solve(remaining):
        if remaining == 0:
            return 0, ()
        chosen_options = None
        bits = remaining
        while bits:
            bit = bits & -bits
            i = bit.bit_length() - 1
            options = [t for t in by_cell[i] if t[0] & remaining == t[0]]
            if not options:
                return -10**6, ()
            if chosen_options is None or len(options) < len(chosen_options):
                chosen_options = options
                if len(options) == 1:
                    break
            bits ^= bit

        best_score, best_tiles = -10**6, ()
        for mask, color, square in chosen_options:
            score, rest = solve(remaining ^ mask)
            score += square
            if score > best_score:
                best_score, best_tiles = score, ((mask, color),) + rest
        return best_score, best_tiles

    score, solution = solve(full)
    if score < 0:
        return [[1 if v == 8 else 0 for v in row] for row in grid]

    out = [[0] * w for _ in range(h)]
    for mask, color in solution:
        for i, (r, c) in enumerate(cells):
            if mask >> i & 1:
                out[r][c] = color
    return out
